@startuml

class Boeing {
  + Name : string
}

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + EmployeeID : string
}

class Salesperson {
  + SalespersonID : string
}

class Contract {
  + ContractID : string
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionID : string
  + Model : string
  + Price : double
  + Options : string
  + DeliveryDate : date
}

class Airplane {
  + SerialNumber : string
  + Model : string
}

Employee --|> Salesperson
Salesperson --|> Employee

Boeing "1" -- "0..*" Contract
Contract "1" -- "1..*" Acquisition
Acquisition "1" -- "1" Airplane
Contract "0..*" -- "0..1" Salesperson
Airline "1" -- "0..*" Contract
Airline "0..1" o-- "0..*" Airline : daughterOf

@enduml

